import{_ as d,a0 as a,w as l,s,ao as p,I as n,x as t,a1 as r,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const F=JSON.parse('{"title":"安卓編年史（13）：Android 2.1, update 1——無盡戰爭的開端 | LCTT x X-CMD","titleTemplate":false,"description":"安卓編年史（13）：Android 2.1, update 1——無盡戰爭的開端 | LCTT (The history of Android) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"安卓編年史（13）：Android 2.1, update 1——無盡戰爭的開端 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"安卓編年史（13）：Android 2.1, update 1——無盡戰爭的開端 | LCTT (The history of Android) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"The history of Android/13 - The history of Android","title":"安卓編年史（13）：Android 2.1, update 1——無盡戰爭的開端","tag":"The history of Android","desc":""},"relativePath":"The history of Android/13 - The history of Android.md","filePath":"[post].md"}'),u={name:"The history of Android/13 - The history of Android.md"};function m(T,o,f,g,h,A){const e=a("Link");return l(),s("div",null,[o[25]||(o[25]=p("",3)),n("p",null,[o[1]||(o[1]=t("谷歌是第一代 iPhone 的主要合作伙伴——公司為蘋果的移動操作系統提供了谷歌地圖、搜索，以及 Youtube。在那時，谷歌 CEO 埃裏克·施密特是蘋果的董事會成員之一。實際上，在最初的蘋果發佈會上，施密特是在史蒂夫·喬布斯",-1)),r(e,{href:"http://www.youtube.com/watch?v=9hUIxyE2Ns8#t=3016"},{default:i(()=>[...o[0]||(o[0]=[t("之後第一個登台的人",-1)])]),_:1}),o[2]||(o[2]=t("，他還開玩笑説兩家公司如此接近，都可以合併成“AppleGoo”了。",-1))]),o[26]||(o[26]=n("p",null,"當谷歌開發安卓的時候，兩家公司間的關係慢慢變得充滿爭吵。然而，谷歌很大程度上還是通過拒 iPhone 關鍵特性於安卓門外，如雙指縮放，來取悦蘋果。儘管如此，Nexus One 是第一部不帶鍵盤的直板安卓旗艦機，設備被賦予了和iPhone 相同的外觀因素。Nexus One 結合了新軟件和谷歌的品牌，這是壓倒蘋果的最後一根稻草。根據沃爾特·艾薩克森為史蒂夫·喬布斯寫的傳記，2010 年 1 月在看到了 Nexus One 之後，這位蘋果的 CEO 震怒了，説道：“如果需要的話我會用盡最後一口氣，以及花光蘋果在銀行裏的 400 億美元，來糾正這個錯誤……我要摧毀安卓，因為它完全是偷竊來的產品。我願意為此發起核戰爭。”",-1)),n("p",null,[o[4]||(o[4]=t("所有的這些都在秘密地發生，僅在 Nexus One 發佈後的幾年後才公諸於眾。公眾們最早在安卓 2.1——推送給 Nexus One 的一個稱作 “",-1)),r(e,{href:"http://arstechnica.com/gadgets/2010/02/googles-nexus-one-gets-multitouch/"},{default:i(()=>[...o[3]||(o[3]=[t("2.1 update 1",-1)])]),_:1}),o[5]||(o[5]=t("” 的更新，發佈後一個月左右捕捉到谷歌和蘋果間愈演愈烈的分歧氣息。這個更新添加了一個功能，正是 iOS 一直居於安卓之上的功能：雙指縮放。",-1))]),o[27]||(o[27]=n("p",null,"儘管安卓從 2.0 版本開始就支持多點觸控 API 了，但系統的默認應用在喬布斯的命令下依然和這項實用的功能劃清界限。在關於 Nexus One 的和解會議談崩了之後，谷歌再也沒有理由拒雙指縮放於安卓門外了。谷歌給設備推送了更新，安卓終於補上了不足之處。",-1)),o[28]||(o[28]=n("p",null,"隨着谷歌地圖、瀏覽器以及相冊中雙指縮放的全面啓用，谷歌和蘋果的智能手機戰爭也就此拉開序幕。在接下來的幾年中，兩家公司會變成死敵。雙指縮放功能更新的一個月後，蘋果開始了它的征途，起訴了所有使用安卓的公司。HTC、摩托羅拉以及三星都被告上法庭，直到現在都還有一些訴訟還沒解決。施密特也辭去了蘋果董事會的職務。谷歌地圖和 Youtube 被從 iPhone 中移除，蘋果甚至開始打造自己的地圖服務。今天，這兩位選手幾乎是 “AppleGoo” 競賽的唯一選手，涉及領域十分廣泛：智能手機、平板、筆記本、電影、TV 秀、音樂、書籍、應用、郵件、生產力工具、瀏覽器、個人助理、雲存儲、移動廣告、即時通訊、地圖以及機頂盒……以及不久它們將會在汽車智能、穿戴設備、移動支付，以及客廳娛樂等進行競爭。",-1)),o[29]||(o[29]=n("h3",{id:"android-2-2-froyo——更快更華麗",tabindex:"-1"},[t("Android 2.2 Froyo——更快更華麗 "),n("a",{class:"header-anchor",href:"#android-2-2-froyo——更快更華麗","aria-label":"Permalink to “Android 2.2 Froyo——更快更華麗”"},"​")],-1)),n("p",null,[r(e,{href:"http://arstechnica.com/information-technology/2010/07/android-22-froyo/"},{default:i(()=>[...o[6]||(o[6]=[t("安卓 2.2",-1)])]),_:1}),o[7]||(o[7]=t(" 在 2010 年 5 月，也就是 2.1 發佈後的四個月後亮相。Froyo（凍酸奶）的亮點主要是底層優化，只為更快的速度。Froyo 最大的改變是增加了 JIT 即時編譯。JIT 自動在運行時將 java 字節碼轉換為原生碼，這會給系統全面帶來顯著的性能改善。",-1))]),o[30]||(o[30]=n("p",null,"瀏覽器同樣得到了性能改善，這要感謝整合了來自 Chrome 的 V8 Javascript 引擎。這是安卓瀏覽器從 Chrome 借鑑的許多特性中的第一個，最終系統內置的瀏覽器會被移動版 Chrome 徹底替代掉。在那之前，安卓團隊還是需要提供一個瀏覽器。從 Chrome 借鑑特性是條升級的捷徑。",-1)),o[31]||(o[31]=n("p",null,"在谷歌專注於讓它的平台更快的同時，蘋果正在讓它的平台更全面。這位谷歌的競爭對手在一個月前發佈了 10 英寸的 iPad，先行進入了平板時代。儘管有些搭載 Froyo 和 Gingerbread 的安卓平板發佈，但谷歌的官方回應——安卓 3.0 Honeycomb（蜂巢）以及摩托羅拉 Xoom——在 9 個月後才來到。",-1)),o[32]||(o[32]=n("p",null,[n("img",{src:"http://cdn.arstechnica.net/wp-content/uploads/2014/02/22-2.png",alt:"Froyo底部添加了雙圖標停靠欄以及全局搜索。"})],-1)),o[33]||(o[33]=n("p",null,[n("em",null,"Froyo 底部添加了雙圖標停靠欄以及全局搜索。 [Ron Amadeo 供圖]")],-1)),o[34]||(o[34]=n("p",null,"Froyo 主屏幕最大的變化是底部的新停靠欄，電話和瀏覽器圖標填充了先前抽屜按鈕左右的空白空間。這些新圖標都是現有圖標的白色定製版本，並且用户沒辦法自己設置圖標。",-1)),o[35]||(o[35]=n("p",null,"默認佈局移除了所有圖標，屏幕上只留下一個使用提示小部件，引導你點擊啓動器圖標以訪問你的應用。谷歌搜索小部件得到了一個谷歌 logo，它同時也是個按鈕。點擊它可以打開一個搜索界面，你可以限制搜索範圍是在互聯網、應用或是聯繫人之內。",-1)),o[36]||(o[36]=n("p",null,[n("img",{src:"http://cdn.arstechnica.net/wp-content/uploads/2014/03/small-market-2.jpg",alt:"下載頁面有了“更新所有”按鈕，這是個 Flash 應用，一個 flash 驅動的一切皆有可能的網站，以及“移動到 SD”按鈕。 "})],-1)),n("p",null,[n("em",null,[o[9]||(o[9]=t("下載頁面有了“更新所有”按鈕，這是個 Flash 應用，一個 flash 驅動的一切皆有可能的網站，以及“移動到 SD”按鈕。 [",-1)),r(e,{href:"http://arstechnica.com/information-technology/2010/07/android-22-froyo/"},{default:i(()=>[...o[8]||(o[8]=[t("Ryan Paul",-1)])]),_:1}),o[10]||(o[10]=t(" 供圖]",-1))])]),o[37]||(o[37]=p("",25)),n("p",null,[r(e,{href:"http://arstechnica.com/author/ronamadeo"},{default:i(()=>[...o[11]||(o[11]=[t("Ron Amadeo",-1)])]),_:1}),o[13]||(o[13]=t(" / Ron是Ars Technica的評論編緝，專注於安卓系統和谷歌產品。他總是在追尋新鮮事物，還喜歡拆解事物看看它們到底是怎麼運作的。 ",-1)),r(e,{href:"https://twitter.com/RonAmadeo"},{default:i(()=>[...o[12]||(o[12]=[t("@RonAmadeo",-1)])]),_:1})]),o[38]||(o[38]=n("hr",null,null,-1)),n("p",null,[o[15]||(o[15]=t("via: ",-1)),r(e,{href:"http://arstechnica.com/gadgets/2016/10/building-android-a-40000-word-history-of-googles-mobile-os/13/"},{default:i(()=>[...o[14]||(o[14]=[t("http://arstechnica.com/gadgets/2016/10/building-android-a-40000-word-history-of-googles-mobile-os/13/",-1)])]),_:1})]),n("p",null,[o[18]||(o[18]=t("譯者：",-1)),r(e,{href:"https://github.com/alim0x"},{default:i(()=>[...o[16]||(o[16]=[t("alim0x",-1)])]),_:1}),o[19]||(o[19]=t(" 校對：",-1)),r(e,{href:"https://github.com/wxy"},{default:i(()=>[...o[17]||(o[17]=[t("wxy",-1)])]),_:1})]),n("p",null,[o[22]||(o[22]=t("本文由 ",-1)),r(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...o[20]||(o[20]=[t("LCTT",-1)])]),_:1}),o[23]||(o[23]=t(" 原創翻譯，",-1)),r(e,{href:"http://linux.cn/"},{default:i(()=>[...o[21]||(o[21]=[t("Linux中國",-1)])]),_:1}),o[24]||(o[24]=t(" 榮譽推出",-1))])])}const b=d(u,[["render",m]]);export{F as __pageData,b as default};
